/**
 * Returns a 204 preflight response with CORS headers.
 * Call this at the top of any public api.* route loader/action.
 */
export function handleCorsOptions(request: Request): Response | null {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }
  return null;
}

import db from "~/db.server";

/**
 * Converts a string to a URL-safe slug.
 * e.g. "My Quiz Title!" -> "my-quiz-title"
 */
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

/**
 * Generates a slug that is unique per shop.
 * Appends a counter suffix if the base slug is already taken.
 */
export async function generateUniqueSlug(shop: string, title: string): Promise<string> {
  const base = slugify(title) || "quiz";
  let slug = base;
  let counter = 0;
  while (await db.quiz.findFirst({ where: { shop, slug } })) {
    counter++;
    slug = `${base}-${counter}`;
  }
  return slug;
}

/**
 * Safely parses a JSON string, returning `fallback` on any parse error.
 * Use this for all Prisma JSON string fields (Law 6).
 */
export function parseSafe<T>(str: string, fallback: T): T {
  try {
    return JSON.parse(str) as T;
  } catch {
    return fallback;
  }
}

/**
 * Formats a number as USD currency.
 * e.g. 29.99 -> "$29.99"
 */
export function formatCurrency(amount: number): string {
  return new Intl.NumberFormat("en-US", {
    style:    "currency",
    currency: "USD",
  }).format(amount);
}

/**
 * Formats a Date or ISO string as a human-readable date.
 * e.g. "2024-03-25T00:00:00Z" -> "Mar 25, 2024"
 */
export function formatDate(date: Date | string): string {
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day:   "numeric",
    year:  "numeric",
  }).format(new Date(date));
}

/**
 * Truncates a string to `maxLength` characters, appending "…" if truncated.
 */
export function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return `${text.slice(0, maxLength - 1)}…`;
}

/**
 * Returns true if the value is a non-null object (not an array).
 */
export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Manual validation helpers — no external validation library required.
 * These functions return `null` on success or an error message string on failure.
 * For form actions: run all validators and collect errors before returning to the client.
 */

// ── Types ─────────────────────────────────────────────────────────────────────

export interface ValidationError {
  field: string;
  message: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function err(field: string, message: string): ValidationError {
  return { field, message };
}

// ── Quiz validators ───────────────────────────────────────────────────────────

const QUIZ_TYPES = [
  "product-recommendation",
  "personality",
  "assessment",
  "survey",
  "lead-gen",
] as const;

const QUIZ_STATUSES = ["draft", "active", "paused", "archived"] as const;

export interface QuizCreateInput {
  title: string;
  type?: string;
  description?: string;
}

export function validateQuizCreate(input: QuizCreateInput): ValidationResult {
  const errors: ValidationError[] = [];

  if (!input.title || input.title.trim().length === 0) {
    errors.push(err("title", "Title is required"));
  } else if (input.title.trim().length > 255) {
    errors.push(err("title", "Title must be 255 characters or fewer"));
  }

  if (input.type && !(QUIZ_TYPES as readonly string[]).includes(input.type)) {
    errors.push(err("type", `Type must be one of: ${QUIZ_TYPES.join(", ")}`));
  }

  if (input.description && input.description.length > 1000) {
    errors.push(err("description", "Description must be 1000 characters or fewer"));
  }

  return { valid: errors.length === 0, errors };
}

export interface QuizUpdateInput {
  title?: string;
  description?: string;
  status?: string;
  settings?: string;
  styling?: string;
}

export function validateQuizUpdate(input: QuizUpdateInput): ValidationResult {
  const errors: ValidationError[] = [];

  if (input.title !== undefined) {
    if (input.title.trim().length === 0) {
      errors.push(err("title", "Title cannot be empty"));
    } else if (input.title.trim().length > 255) {
      errors.push(err("title", "Title must be 255 characters or fewer"));
    }
  }

  if (input.description !== undefined && input.description.length > 1000) {
    errors.push(err("description", "Description must be 1000 characters or fewer"));
  }

  if (input.status !== undefined && !(QUIZ_STATUSES as readonly string[]).includes(input.status)) {
    errors.push(err("status", `Status must be one of: ${QUIZ_STATUSES.join(", ")}`));
  }

  if (input.settings !== undefined) {
    try {
      JSON.parse(input.settings);
    } catch {
      errors.push(err("settings", "Settings must be valid JSON"));
    }
  }

  if (input.styling !== undefined) {
    try {
      JSON.parse(input.styling);
    } catch {
      errors.push(err("styling", "Styling must be valid JSON"));
    }
  }

  return { valid: errors.length === 0, errors };
}

// ── Question validators ───────────────────────────────────────────────────────

const QUESTION_TYPES = [
  "multiple-choice",
  "multiple-choice-multi",
  "image-choice",
  "slider",
  "text-input",
  "email",
  "date",
  "dropdown",
  "rating",
] as const;

export interface QuestionCreateInput {
  quizId: string;
  type: string;
  title: string;
  description?: string;
  required?: boolean;
}

export function validateQuestionCreate(input: QuestionCreateInput): ValidationResult {
  const errors: ValidationError[] = [];

  if (!input.quizId || input.quizId.trim().length === 0) {
    errors.push(err("quizId", "Quiz ID is required"));
  }

  if (!(QUESTION_TYPES as readonly string[]).includes(input.type)) {
    errors.push(err("type", `Type must be one of: ${QUESTION_TYPES.join(", ")}`));
  }

  if (!input.title || input.title.trim().length === 0) {
    errors.push(err("title", "Question title is required"));
  } else if (input.title.trim().length > 500) {
    errors.push(err("title", "Title must be 500 characters or fewer"));
  }

  if (input.description && input.description.length > 1000) {
    errors.push(err("description", "Description must be 1000 characters or fewer"));
  }

  return { valid: errors.length === 0, errors };
}

// ── Answer validators ─────────────────────────────────────────────────────────

export interface AnswerCreateInput {
  questionId: string;
  text: string;
  score?: number;
}

export function validateAnswerCreate(input: AnswerCreateInput): ValidationResult {
  const errors: ValidationError[] = [];

  if (!input.questionId || input.questionId.trim().length === 0) {
    errors.push(err("questionId", "Question ID is required"));
  }

  if (!input.text || input.text.trim().length === 0) {
    errors.push(err("text", "Answer text is required"));
  } else if (input.text.trim().length > 255) {
    errors.push(err("text", "Answer text must be 255 characters or fewer"));
  }

  if (input.score !== undefined) {
    if (!Number.isInteger(input.score)) {
      errors.push(err("score", "Score must be an integer"));
    } else if (input.score < -100 || input.score > 100) {
      errors.push(err("score", "Score must be between -100 and 100"));
    }
  }

  return { valid: errors.length === 0, errors };
}

// ── Email validator ───────────────────────────────────────────────────────────

export function validateEmail(email: string): string | null {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return "Please enter a valid email address";
  }
  return null;
}

// ── Convenience: collect first error message per field ────────────────────────

export function errorsToMap(errors: ValidationError[]): Record<string, string> {
  return errors.reduce<Record<string, string>>((acc, e) => {
    if (!acc[e.field]) acc[e.field] = e.message;
    return acc;
  }, {});
}

